enum SshCoreError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case KeyGenerationError(reason: String
    )
    case KeyParseError(reason: String
    )
    case InvalidSessionName(name: String, reason: String
    )
    case ConnectionError(reason: String
    )
    case AuthenticationError(username: String, reason: String
    )
    case ChannelError(reason: String
    )
    case IoError(reason: String
    )
    case AlreadyConnected
    case NotConnected
    case Timeout
    case ApprovalVerificationError(reason: String
    )
    case InvalidApprovalPayload(reason: String
    )
    case PortForwardFailed(reason: String
    )
    case LocalPortInUse(port: UInt16
    )
    case RemotePortRefused(port: UInt16
    )
    case AiAssistantError(reason: String
    )
    case AiResponseParseError(reason: String
    )
    case TranscriptError(reason: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

